<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import {Activity,Play,Plus,RadioTower,RefreshCw,Server,Wifi} from 'lucide-vue-next';import {useAuthStore} from '@/stores/useAuthStore';import {agentStatusLabel,taskProgress} from '@/features/discovery/discoveryModel'
type Agent={id:string;name:string;hostname:string;ip:string;status:string;version:string;lastHeartbeat:string};type Item={id:string;name:string;ip:string;state:string};type Task={id:string;name:string;scope:string;status:string;discovered:number;imported:number;items?:Item[]};type Summary={total:number;online:number;tasks:number;pending:number}
const auth=useAuthStore(),agents=ref<Agent[]>([]),tasks=ref<Task[]>([]),summary=ref<Summary>(),busy=ref(false),error=ref('');const headers=computed(()=>({Authorization:`Bearer ${auth.token}`,'Content-Type':'application/json'}));async function request<T>(url:string,options?:RequestInit){const r=await fetch(url,{...options,headers:headers.value});if(!r.ok)throw new Error(`请求失败 (${r.status})`);return r.json() as Promise<T>};async function load(){busy.value=true;error.value='';try{[summary.value,agents.value,tasks.value]=await Promise.all([request<Summary>('/api/v1/discovery/summary'),request<Agent[]>('/api/v1/discovery/agents'),request<Task[]>('/api/v1/discovery/tasks')])}catch(e){error.value=e instanceof Error?e.message:'加载失败'}finally{busy.value=false}};async function createTask(){await request<Task>('/api/v1/discovery/tasks',{method:'POST',body:JSON.stringify({name:`网段扫描 ${tasks.value.length+1}`,source:'network',scope:'10.20.0.0/24'})});await load()};async function action(task:Task,type:'run'|'reconcile'){await request<Task>(`/api/v1/discovery/tasks/${task.id}/${type}`,{method:'POST'});await load()};const cidrText=ref('172.28.68.0/24\n172.28.69.0/24');const scanType=ref('physical-server');const scanning=ref(false);const scanResult=ref<{scanned:number;found:number;adopted:number;merged:number;conflicts:number}|null>(null)
async function scanNodeExporter(){scanning.value=true;error.value='';try{const cidrs=cidrText.value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);scanResult.value=await request<{scanned:number;found:number;adopted:number;merged:number;conflicts:number}>('/api/v1/discovery/scan-node-exporter',{method:'POST',body:JSON.stringify({cidrs,defaultType:scanType.value,port:9100})});await load()}catch(e){error.value=e instanceof Error?e.message:'扫描失败'}finally{scanning.value=false}}
const sshCidrs=ref('172.28.69.161/32');const sshScanType=ref('');const sshScanning=ref(false);const sshResult=ref<{scanned:number;found:number;adopted:number;merged:number;conflicts:number}|null>(null)
async function scanSSH(){sshScanning.value=true;error.value='';try{const cidrs=sshCidrs.value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);sshResult.value=await request<{scanned:number;found:number;adopted:number;merged:number;conflicts:number}>('/api/v1/discovery/scan-ssh',{method:'POST',body:JSON.stringify({cidrs,defaultType:sshScanType.value,port:22})});await load()}catch(e){error.value=e instanceof Error?e.message:'SSH 扫描失败'}finally{sshScanning.value=false}}
const aiHosts=ref('172.28.68.56');const aiType=ref('');const aiBusy=ref(false);const aiResult=ref<Array<{host:string;ok:boolean;info:string}>>([])
async function batchInstall(){aiBusy.value=true;error.value='';try{const hosts=aiHosts.value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);aiResult.value=await request<Array<{host:string;ok:boolean;info:string}>>('/api/v1/discovery/agent-install',{method:'POST',body:JSON.stringify({hosts,assetType:aiType.value,port:22})})}catch(e){error.value=e instanceof Error?e.message:'批量安装失败'}finally{aiBusy.value=false}}
onMounted(load)
</script>
<template><section class="discovery-page"><header class="discovery-heading"><div><span>AGENT & AUTO DISCOVERY</span><h1>Agent 与自动发现</h1><p>统一管理采集端在线状态、发现任务与 CMDB 数据入库。</p></div><button class="primary" @click="createTask"><Plus/>新建发现任务</button></header><div v-if="error" class="discovery-error">{{error}}</div><div class="discovery-summary"><article><RadioTower/><div><span>Agent 总数</span><strong>{{summary?.total??0}}</strong></div></article><article><Wifi/><div><span>在线 Agent</span><strong>{{summary?.online??0}}</strong></div></article><article><Activity/><div><span>待纳管资产</span><strong>{{summary?.pending??0}}</strong></div></article><article><Server/><div><span>发现任务</span><strong>{{summary?.tasks??0}}</strong></div></article></div><div class="discovery-grid"><section class="discovery-panel"><header><div><h2>采集端状态</h2><span>实时心跳与版本</span></div><button @click="load"><RefreshCw :class="{spin:busy}"/></button></header><div class="agent-list"><article v-for="agent in agents" :key="agent.id"><i :data-status="agent.status"></i><div><strong>{{agent.name}}</strong><span>{{agent.ip}} · {{agent.hostname}} · v{{agent.version}}</span></div><b :data-status="agent.status">{{agentStatusLabel(agent.status)}}</b><time>{{agent.lastHeartbeat||'尚未连接'}}</time></article></div></section><section class="discovery-panel tasks"><header><div><h2>发现任务</h2><span>扫描、识别并纳管基础设施</span></div></header><article v-for="task in tasks" :key="task.id" class="task-card"><div class="task-title"><div><strong>{{task.name}}</strong><span>{{task.scope}}</span></div><b>{{task.status}}</b></div><div class="task-counts"><span>已发现 <strong>{{task.discovered}}</strong></span><span>已入库 <strong>{{task.imported}}</strong></span><span>纳管率 <strong>{{taskProgress(task)}}%</strong></span></div><div class="task-progress"><i :style="{width:taskProgress(task)+'%'}"></i></div><div v-if="task.items?.length" class="discovered-items"><span v-for="item in task.items" :key="item.id"><Server/>{{item.name}}<small>{{item.ip}}</small><b>{{item.state==='imported'?'已入库':'待入库'}}</b></span></div><footer><button v-if="task.status!=='completed'" @click="action(task,'run')"><Play/>执行扫描</button><button class="primary" :disabled="!task.discovered||task.imported===task.discovered" @click="action(task,'reconcile')">同步至 CMDB</button></footer></article></section><section class="discovery-panel scanner"><header><div><h2>node_exporter 网段扫描</h2><span>输入网段探测 9100，发现主机即自动纳管到 CMDB</span></div></header><div class="scanner-form"><label><span>网段（每行一个）</span><textarea v-model="cidrText" rows="3"></textarea></label><label><span>资产类型</span><select v-model="scanType"><option value="">自动识别（默认物理机）</option><option value="physical-server">物理服务器</option><option value="virtual-machine">虚拟机</option></select></label><button class="primary" :disabled="scanning" @click="scanNodeExporter">{{scanning?'扫描中...':'开始扫描并纳管'}}</button></div><div v-if="scanResult" class="scanner-result">扫描 {{scanResult.scanned}} 台 · 发现 node_exporter {{scanResult.found}} 台 · 新纳管 {{scanResult.adopted}} · 合并刷新 {{scanResult.merged}} · 重复/冲突 {{scanResult.conflicts}}</div></section><section class="discovery-panel ssh-scanner"><header><div><h2>SSH 采集</h2><span>对无法安装 Agent 的主机，通过 SSH 采集并入 CMDB（凭据在服务端 Secret 配置）</span></div></header><div class="scanner-form"><label><span>主机/网段（每行一个）</span><textarea v-model="sshCidrs" rows="3"></textarea></label><label><span>资产类型</span><select v-model="sshScanType"><option value="">自动识别（默认物理机）</option><option value="physical-server">物理服务器</option><option value="virtual-machine">虚拟机</option></select></label><button class="primary" :disabled="sshScanning" @click="scanSSH">{{sshScanning?'采集并纳管中...':'SSH 采集并纳管'}}</button></div><div v-if="sshResult" class="scanner-result">扫描 {{sshResult.scanned}} · 发现 {{sshResult.found}} · 新纳管 {{sshResult.adopted}} · 合并刷新(按IP去重) {{sshResult.merged}} · 重复/冲突 {{sshResult.conflicts}}</div></section><section class="discovery-panel agent-install"><header><div><h2>Agent 批量安装</h2><span>通过 SSH 在目标主机安装并启动 cmdb-agent（二进制由服务端 CMDB_AGENT_BUNDLE_URL 下发）</span></div></header><div class="scanner-form"><label><span>主机 IP（每行一个）</span><textarea v-model="aiHosts" rows="3"></textarea></label><label><span>资产类型</span><select v-model="aiType"><option value="">自动识别（默认物理机）</option><option value="physical-server">物理服务器</option><option value="virtual-machine">虚拟机</option></select></label><button class="primary" :disabled="aiBusy" @click="batchInstall">{{aiBusy?'安装中...':'批量安装 Agent'}}</button></div><div class="ai-results"><p v-for="r in aiResult" :key="r.host" :class="{ok:r.ok}">{{r.host}} → {{r.ok?'成功':'失败'}} · {{r.info}}</p></div></section></div></section></template>
